EXPORT_SYMBOL ( pccard_nonstatic_ops ) ; static ssize_t show_io_db ( struct device * dev , struct device_attribute * attr , char * buf ) { struct pcmcia_socket * s = dev_get_drvdata ( dev ) ; struct socket_data * data ; struct resource_map * p ; ssize_t ret = 0 ; mutex_lock ( & s -> ops_mutex ) ; data = s -> resource_data ; for ( p = data -> io_db . next ; p != & data -> io_db ; p = p -> next ) { ret += sysfs_emit_at ( buf , ret , "0x%08lx - 0x%08lx\n" , ( ( unsigned long ) p -> base ) , ( ( unsigned long ) p -> base + p -> num - 1 ) ) ; } mutex_unlock ( & s -> ops_mutex ) ; return ret ; } 